import { getValueOrField } from '../../utils';
import { DURATION, EASING } from '../../constants';
import type {
    Duration,
    DurationType,
    Easing,
    EasingType,
    FadeThroughOverrideProps,
    VariantsKeys,
    VariantsType,
} from '../../types';

const getTiming = (variant: VariantsKeys, duration: DurationType = 'moderate1', easing: EasingType) => ({
    delay: 0,
    duration: DURATION[getValueOrField(duration, variant) as Duration],
    ease: EASING[getValueOrField(easing, variant) as Easing],
});

const variants: VariantsType<FadeThroughOverrideProps> = {
    enter: ({ cross, duration, delayMultiplier = 1 } = {}) => {
        const easing: EasingType = cross ? 'linear' : 'easeIn';
        const timing = getTiming('enter', duration, easing);
        const delayShift = cross ? timing.duration : 0;

        timing.delay = delayMultiplier * timing.duration - delayShift;

        return { timing, opacity: [1] };
    },
    exit: ({ duration } = {}) => ({
        opacity: [0],
        timing: getTiming('exit', duration, 'easeOut'),
    }),
};

export default variants;
