import React, { useEffect, useState, useRef } from 'react';
import { NodeGroup } from 'react-move';
import { renderChildren } from '@fiverr-private/ui_utils';
import type { ChildrenList, Duration, FadeThroughProps } from '../../types';
import { DURATION } from '../../constants';
import variants from './variants';

const FadeThrough = ({
  cross = false,
  duration = 'moderate1',
  loop = false,
  children,
}: ChildrenList & FadeThroughProps) => {
  const custom = { cross, duration };

  const childrenArray = React.Children.toArray(children);

  const transitionToChildIndexRef = useRef<number>();
  const transitionTimeoutPidRef = useRef<ReturnType<typeof setTimeout>>();

  const [animatedItems, setAnimatedItems] = useState([{ childIndex: 0 }, { childIndex: 1 }]);

  useEffect(() => () => transitionTimeoutPidRef.current && clearTimeout(transitionTimeoutPidRef.current));

  const shiftAnimatedItems = () =>
    setAnimatedItems(([first, second]) => {
      const getNextItem = ({ childIndex }: { childIndex: number }) => ({
        childIndex: (childIndex + 1) % childrenArray.length,
      });
      return [getNextItem(first), getNextItem(second)];
    });

  const handleAnimationStart = (_data: any, index: number) => ({
    opacity: index === 0 ? 1 : 0,
  });

  const handleAnimationUpdate = (_data: any, index: number) =>
    index === 0 ? variants.exit(custom) : variants.enter({ ...custom, delayMultiplier: index });

  const maybeScheduleAnimatedItemsShift = (
    animatedItemKey: number,
    animatedItemIndex: number,
    animatedItemState: { opacity: number }
  ) => {
    const isAllAnimated = !loop && animatedItems[1].childIndex === childrenArray.length - 1;
    const isShiftScheduled = transitionToChildIndexRef.current === animatedItemKey;
    const isTransitionFromItem = animatedItemIndex === 0;
    const isTransitionInProcess = animatedItemState.opacity !== 1;

    if (isAllAnimated || isShiftScheduled || isTransitionFromItem || isTransitionInProcess) {
      return;
    }

    transitionToChildIndexRef.current = animatedItemKey;
    transitionTimeoutPidRef.current = setTimeout(() => shiftAnimatedItems(), DURATION[duration as Duration]);
  };

  return (
    <NodeGroup
      data={animatedItems}
      keyAccessor={({ childIndex }) => childIndex}
      start={handleAnimationStart}
      enter={handleAnimationUpdate}
      update={handleAnimationUpdate}
    >
      {(nodes) => (
        <div style={{ position: 'relative' }}>
          {nodes.map(({ key, state }, index) => {
            maybeScheduleAnimatedItemsShift(key, index, state);

            const element = childrenArray[key];
            const style = React.isValidElement(element) && element.props ? element.props.style : {};

            return renderChildren(childrenArray[key], {
              style: {
                ...style,
                position: index === 1 && state.opacity !== 1 ? 'absolute' : undefined,
                top: 0,
                left: 0,
                display: state.opacity === 0 ? 'none' : undefined,
                opacity: state.opacity,
              },
            });
          })}
        </div>
      )}
    </NodeGroup>
  );
};

FadeThrough.displayName = 'FadeThrough';

export default FadeThrough;
